package com.aistock.market.ingestion;
import com.aistock.market.version.*;import com.aistock.market.support.MarketDatabaseFixture;import com.aistock.market.quotation.RawBar;import com.aistock.common.BusinessException;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class RevisionEventMysqlTest {
 MarketCandidate c(String op,String price,Long rev){var p=new BigDecimal(price);return new MarketCandidate(op,"SH600030","SH600030","test",false,"UNKNOWN","baostock","RAW",Instant.parse("2026-09-27T08:00:00Z"),"source","a".repeat(64),List.of(new RawBar(LocalDate.parse("2026-09-24"),p,p,p,p,BigDecimal.TEN,BigDecimal.TEN,1,null)),List.of(),rev);}
 @Test void changesAreDurableDedupedAndReturningHeadGetsNewEvent(){var f=new MarketDatabaseFixture();var s=new PublicationService(new MarketVersionRepository(f.jdbc()),new CandidateValidator());var q=new RevisionEventRepository(f.jdbc());var a=s.publish(c("a","10",0L));s.publish(c("a","10",0L));s.publish(c("b","10",1L));assertEquals(1,q.events(0,50).items().size());var b=s.publish(c("c","11",1L));s.publish(c("d","10",2L));var events=q.events(0,50).items();assertEquals(3,events.size());assertEquals(a.versionId(),events.get(0).rawVersionId());assertEquals(b.versionId(),events.get(1).rawVersionId());assertEquals(a.versionId(),events.get(2).rawVersionId());assertTrue(events.get(2).eventId()>events.get(1).eventId());assertEquals(1,q.events(events.get(1).eventId(),1).items().size());assertThrows(BusinessException.class,()->q.events(-1,1));assertThrows(BusinessException.class,()->q.events(0,51));}
 @Test void failedPublicationCannotLeaveEventOrAdvanceSequence(){var f=new MarketDatabaseFixture();var s=new PublicationService(new MarketVersionRepository(f.jdbc()),new CandidateValidator());var q=new RevisionEventRepository(f.jdbc());s.publish(c("a","10",0L));assertThrows(BusinessException.class,()->s.publish(c("bad","11",0L)));assertEquals(1,q.events(0,50).items().size());assertEquals(1L,f.jdbc().queryForObject("select last_id from market_revision_sequence where singleton_id=1",Long.class));}
 @Test void failureAfterEventInsertRollsBackHeadEventAndCounter(){var f=new MarketDatabaseFixture();var s=new PublicationService(new MarketVersionRepository(f.jdbc()),new CandidateValidator());var q=new RevisionEventRepository(f.jdbc());var old=s.publish(c("a","10",0L));f.jdbc().execute("create trigger revision_test_failure before update on market_revision_sequence for each row signal sqlstate '45000' set message_text='isolated rollback test'");try{assertThrows(RuntimeException.class,()->s.publish(c("b","11",1L)));assertEquals(1,q.events(0,50).items().size());assertEquals(old.versionId(),f.jdbc().queryForObject("select version_id from instrument_data_head",String.class));assertEquals(1L,f.jdbc().queryForObject("select last_id from market_revision_sequence where singleton_id=1",Long.class));}finally{f.jdbc().execute("drop trigger revision_test_failure");}s.publish(c("c","12",1L));assertEquals(2L,q.events(0,50).items().get(1).eventId());}
}
